-- Alta del noveno cliente: Cámara de Turismo del Estado Mérida (CATUREM).
-- Correr en el SQL Editor de Supabase — la app lo va a recoger solo al
-- cargar (mismo mecanismo de "clientes agregados" que usa el botón
-- "Añadir cliente" desde la propia app, así que no hace falta reiniciar
-- nada ni tocar código).
--
-- Color: #2B8CB0 — el siguiente color libre de la paleta (los primeros 8
-- ya los usan los clientes existentes), mismo criterio automático que usa
-- el botón "Añadir cliente" al elegir color para uno nuevo.
-- Ícono: "landmark" — es el más institucional del catálogo disponible,
-- coherente con que es una cámara/organismo, no una agencia de viajes
-- (ese lugar ya lo ocupa el ícono "compass" de Atlantic HS Tours).

insert into clients (name, color, "iconKey", "logoSvg")
